// Motion Prompt #192 · MIT License (c) 2026 Shohei Ohtaki · https://showheyohtaki.github.io/motion-prompt/#192
//
// Montage / モンタージュ
// Pack: camera2 (Camera moves & transitions, part 2) · element 24 · Category: Transitions & Editing
// What happens: Seven short shots show thirty days of training; straight cuts, with the date jumping at top right.
// Motion spec:
//   - Seven shots joined by straight cuts (0 frames): 0.75 / 0.7 / 0.65 / 0.65 / 0.65 / 0.6 / 0.7 s (4.7 s in all); the date at top right jumps DAY 1 → 3 → 7 → 12 → 20 → 28 → 30
//   - Shots: 1 tracking a runner (legs at t×14), 2 a jump in the park, 3 sunrise (sun rising from 4 m to 12 m), 4 arms raised from a low angle, 5 walking in the city (focal length 420 px), 6 circling the person from -0.3 to +0.3 rad, 7 arms raised in front of a flag
//   - Thirty days of training condensed into 4.7 s; camera position, height and focal length change with every shot (#041 Jump cut keeps the same framing)
//   - Bottom strip: seven sections, only the current shot in blue; the last 0.3 s cross-fades back to the start of the first shot
// When to use it: To show a long period of change or effort in a short time.
// Tags: montage, sequence, training montage, time passing, quick cuts, edit
// Size: 539x208 px · Cycle: 9.4 s
// Needs: kit camera2 -> https://showheyohtaki.github.io/motion-prompt/api/v1/kit/camera2.js
// Live demo: https://showheyohtaki.github.io/motion-prompt/#192
//
// cells[i](k, w, h, u): k = CanvasRenderingContext2D (already cleared and wrapped in save/restore by the caller), w,h = size, u = seconds in [0, cycle). The picture depends only on u.
// Element code starts here. CELLS, constants and helpers live in the kit.

// @element 24
// 24 モンタージュ: 7つの短いカットで30日分の練習を見せる。つなぎは直結、右上に日付
const MT = [
  [0.75, 1, (kk, w, h, t) => world(kk, w, h, cam({ x: t * 2.2 - 1, y: 1.3 }), { person: { x: t * 2.2 - 1, z: 6, walk: t * 14 }, fg: [[-3, 4], [-1.4, 4], [0.2, 4], [1.8, 4], [3.4, 4]] })],
  [0.7, 3, (kk, w, h, t) => world(kk, w, h, cam({ y: 1.3 }), { person: { z: 7, y: jumpY(P(t, 0.05, 0.7)), armUp: true }, buildings: false })],
  [0.65, 7, (kk, w, h, t) => world(kk, w, h, cam({ y: 1.6, pitch: 0.1 }), { sun: [20, lerp(4, 12, t / 0.65), 170], sunCol: C.blueM, buildings: false, trees: false, clouds: [[-30, 20, 110, 2.6], [40, 26, 150, 3.2]] })],
  [0.65, 12, (kk, w, h, t) => world(kk, w, h, cam({ y: 0.5, pitch: 0.25 }), { person: { z: 4.5, armUp: true }, tower: [-3, 22] })],
  [0.65, 20, (kk, w, h, t) => world(kk, w, h, cam({ y: 1.5, f: 420 }), { city: true, mountains: false, person: { z: 7, walk: t * 9, x: -0.5 + t * 0.6 } })],
  [0.6, 28, (kk, w, h, t) => { const a = lerp(-0.3, 0.3, t / 0.6); world(kk, w, h, cam({ x: Math.sin(a) * 6, z: 9 - Math.cos(a) * 6, yaw: -a, y: 1.7, pitch: -0.07 }), { person: { z: 9, face: a }, ring: [0, 9, 10], trees: false }); }],
  [0.7, 30, (kk, w, h, t) => world(kk, w, h, cam({ y: 1.4 }), { person: { z: 6, armUp: true }, extra: [[1.4, 0, 6.3, (k2) => { k2.fillStyle = C.g4; k2.fillRect(-0.04, 0, 0.08, 2.6); k2.fillStyle = C.blue; k2.beginPath(); k2.moveTo(0.04, 2.6); k2.lineTo(0.9, 2.3); k2.lineTo(0.04, 2.0); k2.fill(); }]] })],
];
CELLS[23] = shot((k, w, h, u) => {
  let i = 0, t0 = 0; while (i < MT.length - 1 && u >= t0 + MT[i][0]) { t0 += MT[i][0]; i++; }
  const r = P(u, CYC - 0.3, CYC);
  blend(k, kk => MT[i][2](kk, w, h, u - t0), kk => MT[0][2](kk, w, h, 0), eIOs(r));   // 最後の0.3秒で最初のカットへ戻す
  const segs = []; let s = 0; MT.forEach(([d, day], j) => { segs.push([s, s + d, '', j === i ? C.blue : C.g2]); s += d; });
  strip(k, w, h, segs, u);
  return `DAY ${r > .5 ? MT[0][1] : MT[i][1]}`;
});
